/**
 * 插件模組導出
 *
 * Control Bar 是核心功能，不是插件
 * 這裡導出擴展核心的插件和控制列功能插件
 */

// === 控制列功能插件 ===

// 播放按鈕插件
export { PlayButtonPlugin, PlayButtonManager } from './play-button';
export type { PlayButtonPluginOptions } from './play-button';

// 逐幀步進插件
export { FrameStepPlugin, FrameStepManager } from './frame-step';
export type { FrameStepPluginOptions } from './frame-step';

// 音量插件
export { VolumePlugin, VolumeManager } from './volume';
export type { VolumePluginOptions } from './volume';

// 時間顯示插件
export { TimeDisplayPlugin, TimeDisplayManager } from './time-display';
export type { TimeDisplayPluginOptions } from './time-display';

// 進度條插件
export { ProgressPlugin, ProgressManager } from './progress';
export type { ProgressPluginOptions } from './progress';

// 播放速度插件
export { SpeedPlugin, SpeedManager } from './speed';
export type { SpeedPluginOptions } from './speed';

// 循環按鈕插件
export { LoopButtonPlugin, LoopButtonManager } from './loop-button';
export type { LoopButtonPluginOptions } from './loop-button';

// 全螢幕插件
export { FullscreenPlugin, FullscreenManager } from './fullscreen';
export type { FullscreenPluginOptions } from './fullscreen';

// === 擴展功能插件 ===

// 快捷鍵插件
export { KeyboardPlugin, KeyboardManager } from './keyboard';
export type { KeyboardPluginOptions, KeyboardShortcut } from './keyboard';

// A-B 循環插件
export { ABLoopPlugin, ABLoopManager } from './ab-loop';
export type { ABLoopPluginOptions } from './ab-loop';

// 縮圖預覽插件
export { ThumbnailPlugin, ThumbnailManager } from './thumbnail';
export type { ThumbnailPluginOptions } from './thumbnail';

// HDR 插件
export { HdrPlugin, HdrManager } from './hdr';
export type { HdrPluginOptions, HdrInfo } from './hdr';

// 除錯插件
export { DebugPlugin, DebugManager } from './debug';
export type { DebugPluginOptions, DebugPanelPosition } from './debug';

// 筆記插件
export { NotePlugin, NoteManager } from './notes';
export type { NotePluginOptions, Note } from './notes';

// === 插件集合 ===

import { PlayButtonPlugin } from './play-button';
import { FrameStepPlugin } from './frame-step';
import { VolumePlugin } from './volume';
import { TimeDisplayPlugin } from './time-display';
import { ProgressPlugin } from './progress';
import { SpeedPlugin } from './speed';
import { LoopButtonPlugin } from './loop-button';
import { FullscreenPlugin } from './fullscreen';
import { KeyboardPlugin } from './keyboard';
import { ABLoopPlugin } from './ab-loop';
import { HdrPlugin } from './hdr';
import { DebugPlugin } from './debug';
import { NotePlugin } from './notes';

// 預設控制列插件
export const defaultControlPlugins = [
    PlayButtonPlugin,
    FrameStepPlugin,
    VolumePlugin,
    TimeDisplayPlugin,
    ProgressPlugin,
    SpeedPlugin,
    LoopButtonPlugin,
    FullscreenPlugin,
];

// 預設擴展插件
export const defaultExtensionPlugins = [
];

// 預設插件（僅控制列）
export const defaultPlugins = [
    ...defaultControlPlugins,
    ...defaultExtensionPlugins,
];

// 所有可用插件
// 注意：ThumbnailPlugin 的功能已合併到 ProgressPlugin 中
// ThumbnailPlugin 仍可單獨使用，但不再包含在預設插件集中
export const allPlugins = [
    ...defaultControlPlugins,
    KeyboardPlugin,
    ABLoopPlugin,
    HdrPlugin,
    DebugPlugin,
    NotePlugin,
];
